NAVY=colors.HexColor('#0B1D32'); TEXT=colors.HexColor('#1A2433'); PALE=colors.HexColor('#EAF1F7'); OFF=colors.HexColor('#F7F9FC'); CYAN=colors.HexColor('#0A8FC2'); ORANGE=colors.HexColor('#F2E6D7'); GREEN=colors.HexColor('#E7F0EC'); MUTED=colors.HexColor('#5F6B78'); RULE=colors.HexColor('#C7D1DB')
PW,PH=A4; LEFT=RIGHT=18*mm; TOP=20*mm; BOTTOM=16*mm

def extract_figure(nb_path, title, output_path):
    nb=json.loads(Path(nb_path).read_text())
    for c in nb['cells']:
        src=''.join(c.get('source',[]))
        if title not in src: continue
        for o in c.get('outputs',[]):
            d=o.get('data',{})
            if 'image/png' in d:
                b=d['image/png']; b=''.join(b) if isinstance(b,list) else b
                im=PILImage.open(BytesIO(base64.b64decode(b))).convert('RGB')
                im=im.crop((0,35,im.width,im.height))
                im.save(output_path)
                return
    raise RuntimeError('Figure not found: '+title)

extract_figure('04_segments_robustness.ipynb','Shuffled vs Ordered Validation','_biz_validation.png')
extract_figure('05_final_validation_reporting.ipynb','Period-Local Lift by Call Depth','_biz_lift.png')

